import{_ as p,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"爻徵第十六","description":"杭氏易學 - 爻徵第十六","frontmatter":{"title":"爻徵第十六","description":"杭氏易學 - 爻徵第十六"},"headers":[],"relativePath":"classics/hangshi/017.md","filePath":"classics/hangshi/017.md"}'),r={name:"classics/hangshi/017.md"};function i(n,a,c,_,o,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="爻徵第十六" tabindex="-1">爻徵第十六 <a class="header-anchor" href="#爻徵第十六" aria-label="Permalink to “爻徵第十六”">​</a></h1><p>徵者，用之見乎外者也。壽陽閻氏《爻徵廣義》，詳於鄭氏爻辰，殊於實用無徵焉。六爻制用，肆應不窮，皆以五行陽幹陰支為綱領，以生克刑害少壯盛休廢類別去取，以徵吉凶。以其與卦爻象數，相為統系，足以推六十四卦變化往來之跡。且有與經傳互相發明者，亦初學所不可不知者也。爰取《京氏易》與《易緯》諸書之著錄者，分隸六爻，徵爻用，亦以存古義也。至推演條理，今密於古，術家所習用，更毋庸備述焉。</p><p>六親</p><p>京氏曰：“八卦鬼為系爻，財為制爻，天地為義爻，福德為寶爻，同氣為專爻。”此五者，今術家謂之六親 【親者，族也。《易》曰“類族辨物”，先辨諸爻。】 ，蓋與本身為六也。相傳甚古，義簡而賅，言佔者所不能廢。朱子《周易本義》，以周孔之《易》為教人卜筮之用，而焦京之言卜筮者，反悉廢之，僅以六爻之動靜為佔，宜其無徵驗之可言也。茲以京說為主，而以近世皆用者附之。非敢謂援古證今，亦發其凡而已。</p><p>五者與本身為六。今稱六親者，義亦近古。親者族也。類族辨物，舉一起例，凡言兄弟，則比肩者可類；言子孫，則後我者可類；言父母，則庇我者皆其類；言妻財，則奉我者皆其類；言官鬼，則制我害我者皆其類。遠近不同，則親疏自異。而為利為害，爰有重輕之別。是在察其爻之所在，而鑑別之，非可概論也。</p><p>六神</p><p>神 【神者存也。成性存存，陰陽不測，假定其名，亦猶類族辨物之意也。】 也者，妙萬物而為言。過化存神，有非可以跡象求之者。六親征其實，六神徵諸虛。周流六虛，無乎不在。渺焉漠焉，將何從徵？曰陰陽之氣，布為五行，其幾甚微。《傳》曰：“本於陰陽而立卦，陰陽變化，而神寓也。”此六爻之神所由名，要非泥其名以為實者也。</p><p>《傳》曰：“前朱雀而後玄武，左青龍而右白虎。”古者五行各有專官，官世其守，功德在民，民不能忘。即假人名以神號，舉其名知其用，所以便事也。吉凶神煞之名，皆此類也。必求其人以實之，愚也。必妄其名而斥之，亦詎足為智哉！六壬、太乙、遁甲之言神，舉可隅反矣。</p><p>六屬</p><p>六屬者以五音分屬六爻，即本於納音。納音與納甲相表裡。屬之於爻，仍隨八卦之納甲以定其數也。舉例如下：</p><p>不言乾坤，六子之爻，皆乾坤之爻也。《說卦》“神也者”一章，不言乾坤，非特六子之用，皆乾坤之用。而所謂神者，即乾坤之陰陽不測，周流六虛者也。納音之說似淺而實深。精微之理，非可以跡象求之。謂之音者，乾坤爻辰左行右行。間辰六位，即六律六呂，相生之所本，故以分屬六爻，各納其辰，而謂之納音。今術家占筮推演及風角堪輿諸家，均不能廢納音以為言，而莫知其所由來。因備六爻所屬，並列《內經》及揚子云、抱朴子諸家之圖於後，庶閱者可悉其始末矣。</p><p>納音始於黃帝，今《內經》所載最詳。京氏六十律與甲子分配，自是古法。蓋以一律納五音，十二律納六十音。《內經》五音，始於金，傳火傳木傳水傳土。陽律陰呂，隔八相生。葛稚川曰：“一言得之者，宮與土 【所屬者即一言而得】 。三言得之者，徵與火 【如戊去庚三位，故曰三言。下仿此】 。五言得之者，羽與水。七言得之者，商與金。九言得之者，角與木。故子午九，醜未八，寅申七，卯酉六，辰戌五，巳亥四也。”揚子云《太玄》以火土木金水為序，與《內經》不同。甲子乙丑金者，言甲乙子午其數九，乙庚醜未其數八，甲乙子醜積數三十四，以五除之餘四，故為金。餘仿此數，列右圖：</p><p>按：甲己子午九，乙庚辛未八，丙辛寅申七，丁壬卯酉六，戊癸辰戌五，巳亥四 【己亥對宮亥空為虛，己與虛對為孤，己亥者孤虛之數也。】 。黃梨洲先生《象數論》所評議者，頗多未當。其謂甲子乙丑金者，甲九子九，乙八醜八，積三十四，以五除之餘四故為金。其數則是，其術則非也。故於丙寅丁卯，丙七寅七丁六卯六積二十六，以五陰之餘一故為火，便不成文矣。金四為一當為水，何以為火？而猶曰餘准此將無一能合者矣。蓋納音得數之算法，當以大衍為本。以大衍之數五十去一，除去甲己子午之積數，餘則以五除之，得一則屬水，水生木，其納音為木。丙寅丁卯之為火，當以積數二十六，除大衍五十去一，餘二十三，以五除之餘三，屬木，木生火，故納音為火。甲子乙丑之積三十四，以除大衍去一餘五，五屬土，土生金。非三十四餘五餘四之謂也。</p><p>納音納甲，與天干地支，皆始於黃帝。蓋自伏羲畫卦，利用宜民，至神農黃帝，文明日進，變化益繁。非單純八卦之象數所能濟用，故益之以陰陽五行。天五地六，迎日推歷，布算測地，以盡八卦之用。所謂“窮則變，變則通，通則久”。納甲取先天，法象乎日月，仰以觀於天文也。納音以先天合後天，取數於陰陽十二消息，以布五行，俯以察於地理也。故京孟之《易》，悉本於此。朱元升《三易備遺》推衍納音最詳，巳亥數伏，一六相合，以為即《歸藏》之數，非無見也。</p>',14)])])}const m=p(r,[["render",i]]);export{h as __pageData,m as default};
